(async()=>{
 const checks=[],check=(ok,name)=>{checks.push({name,pass:Boolean(ok)});if(!ok)throw Error(name)},wait=()=>new Promise(r=>setTimeout(r,250));
 const saved=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 const go=async route=>{location.hash=route;await wait();};
 const click=async(label,root=document)=>{const el=[...root.querySelectorAll('button,a')].find(el=>el.textContent.trim()===label||el.getAttribute('aria-label')===label);check(el,'Control '+label);el.click();await wait();};
 const fill=async(label,value,root=document)=>{const el=label==='执行指令'?root.querySelector('.composer textarea'):root.querySelector(`[name="${label}"]`);check(el,'Field '+label);Object.getOwnPropertyDescriptor(el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));await wait();};
 const choose=async(label,contains,root)=>{root.querySelector(`[role=combobox][aria-label="${label}"]`).click();await wait();const option=[...document.querySelectorAll('[role=option]')].find(el=>el.textContent.includes(contains));check(option,'Choice '+contains);option.click();await wait();};
 const dialog=()=>[...document.querySelectorAll('dialog[open]')].at(-1);
 await go('/p/launch/work-items/W-104?tab=executions');await click('创建任务交互执行');await choose('执行节点与已登记 Runtime','Claude Code',dialog());await choose('授权场景（本地模拟）','逐项请求Human授权',dialog());await click('创建等待启动的执行',dialog());let e=saved().executions.at(-1);
 await go(`/chat?execution_id=${e.id}`);await click('模拟节点接受并启动');await fill('操作依据','local node receipt',dialog());await click('模拟节点接受并启动',dialog());
 await fill('执行指令','Provide a candidate with explicit review input');await click('提交执行指令');await click('模拟采用');await fill('操作依据','accepted local turn',dialog());await click('模拟采用此轮次',dialog());
 const request=async(kind,title)=>{await click(kind);await fill('请求标题',title,dialog());if(kind==='模拟Runtime输入请求')await fill('需要Human补充的信息','Which audience should this target?',dialog());await fill('已脱敏的请求详情','Bounded local request; no real tool runs',dialog());await click('创建本地模拟请求',dialog());return saved().executions.find(row=>row.id===e.id).interactions.at(-1);};
 const tool=await request('模拟工具授权请求','One bounded tool action');let card=document.querySelector(`[data-segment="interaction:${tool.id}"]`);check(card,'Tool request visible');await click('允许一次',card);await click('保存本地决定',dialog());let live=saved().executions.find(row=>row.id===e.id);check(live.interactions[0].state==='DECIDED'&&!live.interactions[0].deliveredAt,'Decision saved separately from delivery');check(live.events.every(event=>!event.text.includes('Bounded local request')),'Audit excludes request details');card=document.querySelector(`[data-segment="interaction:${tool.id}"]`);await click('模拟决定送达',card);check(saved().executions.find(row=>row.id===e.id).interactions[0].state==='DELIVERED','Explicit local delivery receipt');
 const input=await request('模拟Runtime输入请求','Audience decision');card=document.querySelector(`[data-segment="interaction:${input.id}"]`);await click('提交结构化输入',card);await fill('回应JSON对象','[]',dialog());await click('保存本地决定',dialog());check(dialog()?.textContent.includes('JSON对象'),'Array rejected inside form');check(saved().executions.find(row=>row.id===e.id).interactions.at(-1).state==='PENDING','Invalid input changes no request state');await fill('回应JSON对象','{"answer":"new customers"}',dialog());await click('保存本地决定',dialog());card=document.querySelector(`[data-segment="interaction:${input.id}"]`);await click('模拟送达失败',card);check(card.textContent.includes('未送达')||document.querySelector(`[data-segment="interaction:${input.id}"]`).textContent.includes('未送达'),'Failed delivery retains visible decision and closure');
 const expiry=await request('模拟Runtime输入请求','Timed request');card=document.querySelector(`[data-segment="interaction:${expiry.id}"]`);await click('模拟时钟推进至到期',card);check(saved().executions.find(row=>row.id===e.id).interactions.at(-1).state==='EXPIRED','Expiry is terminal and explicitly simulated');
 const pending=await request('模拟工具授权请求','Interrupted tool request');card=document.querySelector(`[data-segment="interaction:${pending.id}"]`);await click('允许一次',card);await click('保存本地决定',dialog());await click('模拟连接中断');await fill('操作依据','connection interrupted before delivery',dialog());await click('模拟连接中断',dialog());live=saved().executions.find(row=>row.id===e.id);check(live.interactions.at(-1).closedReason==='DELIVERY_FAILED'&&live.interactions.at(-1).responseAction==='ACCEPT','Interrupted undelivered decision preserved, not replayed');check(saved().work.find(w=>w.id==='W-104').status==='待验收','Interaction lifecycle does not accept work');check(location.hash.includes(e.id)&&document.documentElement.scrollWidth<=innerWidth,'Exact execution route and no viewport overflow');
 return {pass:true,width:innerWidth,checks,executionId:e.id};
})()
